    "excerpt": "Tháng 5 không tĩnh lặng\nAi gieo một cơn mê\nNụ cười anh toả nắng",
    "body": "Tháng 5 không tĩnh lặng\nAi gieo một cơn mê\nNụ cười anh toả nắng\nTay anh gọi mưa về\n\nXin tháng 5 dừng lại\nNgười miết mải sơn khê\nTa thành dòng sông đợi\nThuyền xa bến chưa về\n\nXin tháng 5 cơn gió\nDịu lòng ta tái tê\nCơn mưa nào nức nở\nGhen với tình phu thê\n\nTháng 5 mang cơn bão\nXô dạt ngày bình yên\nVà ta từ độ ấy\nTrái tim chia hai miền…\n\n31/05/2022",
