    "sequence": 40,
    "title": "BÂY GIỜ THÁNG TÁM RỒI ANH",
    "slug": "bay-gio-thang-tam-roi-anh",
    "year": 2022,
    "date": "2022-08-01",
    "excerpt": "Bây giờ tháng Tám rồi anh\nMùa thu lại cồn ngực nhớ\nNgười đi xa làm cơn gió",
    "body": "Bây giờ tháng Tám rồi anh\nMùa thu lại cồn ngực nhớ\nNgười đi xa làm cơn gió\nTa như cây đứng bồn chồn\n\nTháng Tám mưa em buồn hơn\nNắng bên phương anh có rát\nVòng tay hôm nào bỏng khát\nNụ hôn còn ngọt trên môi\n\nThêm ba mươi ngày nữa thôi\nLại đếm ba mươi ngày nữa\nThêm những hoàng hôn dang dở\nĐại dương ngăn trở đôi mình\n\nTháng Tám về cùng bình minh\nTên anh loang vào mây trắng\nEm mơ mình là hạt nắng\nHôn lên vầng trán thanh tân…\n\n1/8/2022",
