    "excerpt": "Tháng 12 là lời giã biệt của năm\nNhư nụ hôn cuối cùng\nXiết trên đôi môi mùa đông",
    "body": "Tháng 12 là lời giã biệt của năm\nNhư nụ hôn cuối cùng\nXiết trên đôi môi mùa đông\nĐêm nối đêm đẩy ngày trôi đi mất\nTháng 12 là kết thúc\nNhưng với em là bắt đầu\n\nTháng 12 che lấp hết trăng sao\nPhả xuống những cơn mưa và giấu đi cơn nắng\nGió lạnh từng hồi\nSóng dội về từ phương trời xa thẳm\nMắt anh màu khói nhớ miên man\n\nNgày rụng dần cho em gần thêm anh\nCho em chạm vào anh\nBỡ ngỡ nhưng mà thân thuộc\nTa quen nhau lâu chưa\nHay đã hẹn từ muôn năm trước\nSao đến tận bây giờ\nMới có một\nTháng\nMười\nHai…\n\n9/12/2023",
